import hashlib, time, os
from cryptography.hazmat.primitives import hashes

data = os.urandom(20_000 * 1024)
print('data size', len(data))

def bench(fn, n=5):
    times = []
    for _ in range(n):
        t0 = time.perf_counter()
        fn()
        times.append(time.perf_counter()-t0)
    return min(times)

def crypto():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def hl():
    return hashlib.sha256(data).digest()

def hl2():
    h = hashlib.sha256()
    h.update(data)
    return h.digest()

print('crypto', bench(crypto), crypto()[:8])
print('hashlib', bench(hl), hl()[:8])
print('hashlib2', bench(hl2))
print('match', crypto()==hl())
