{"command":"python3 << 'PY'
import ctypes, ctypes.util

libcrypto = ctypes.CDLL(ctypes.util.find_library('crypto'))
fn = libcrypto.sha256_multi_block
fn.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_int]
fn.restype = None

IV = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19]

class HASH_DESC(ctypes.Structure):
    _fields_ = [("ptr", ctypes.c_void_p), ("blocks", ctypes.c_int), ("pad", ctypes.c_int)]

class SHA256_CTX(ctypes.Structure):
    _fields_ = [
        ("h", ctypes.c_uint32 * 8),
        ("Nl", ctypes.c_uint32),
        ("Nh", ctypes.c_uint32),
        ("data", ctypes.c_uint32 * 16),
        ("num", ctypes.c_uint32),
        ("md_len", ctypes.c_uint32),
    ]
SHA256_Init = libcrypto.SHA256_Init
SHA256_Init.argtypes = [ctypes.POINTER(SHA256_CTX)]
SHA256_Update = libcrypto.SHA256_Update
SHA256_Update.argtypes = [ctypes.POINTER(SHA256_CTX), ctypes.c_void_p, ctypes.c_size_t]

data = b'a'*64
ctx = SHA256_CTX(); SHA256_Init(ctypes.byref(ctx)); SHA256_Update(ctypes.byref(ctx), data, len(data))
expected = list(ctx.h)
print('expected', [hex(x) for x in expected])

def run(init):
    state = (ctypes.c_uint32 * 64)()
    init(state)
    descs = (HASH_DESC * 4)()
    buf = ctypes.create_string_buffer(data)
    for i in range(4):
        descs[i].ptr = ctypes.cast(buf, ctypes.c_void_p)
        descs[i].blocks = 1
    fn(state, descs, 1)
    return list(state[:40])

def st_inter(state):
    for w in range(8):
        for lane in range(4):
            state[w*4+lane] = IV[w]
def st_lane(state):
    for lane in range(4):
        for w in range(8):
            state[lane*8+w] = IV[w]
def st_bswap(state):
    for w in range(8):
        v = int.from_bytes(IV[w].to_bytes(4,'big'), 'little')
        for lane in range(4):
            state[w*4+lane] = v

for name, fninit in [('inter', st_inter), ('lane', st_lane), ('bswap', st_bswap)]:
    words = run(fninit)
    print(name, [hex(w) for w in words[:32]])
    hits = [hex(w) for w in words if w in expected]
    print('  hits', hits)
