#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <sys/mman.h>
#include <pthread.h>

typedef struct { void *ptr; int blocks; int pad; } HASH_DESC;
extern void sha256_multi_block(void *state, HASH_DESC *desc, int num);

static volatile int which = 0;
static void ontrap(int sig) {
    fprintf(stderr, "TRAP which=%d\n", which);
    _exit(0);
}

int main() {
    void *fn = (void*)sha256_multi_block;
    uintptr_t slide = (uintptr_t)fn - 0x23e6c0;
    uintptr_t targets[3] = {slide + 0x241760, slide + 0x240ec0, slide + 0x23e6de};
    const char *names[3] = {"avx","shaext","scalar"};
    signal(SIGTRAP, ontrap);
    signal(SIGILL, ontrap);

    // make pages writable
    for (int i=0;i<3;i++) {
        uintptr_t page = targets[i] & ~0xFFFULL;
        if (mprotect((void*)page, 0x2000, PROT_READ|PROT_WRITE|PROT_EXEC) != 0) {
            perror("mprotect"); return 1;
        }
    }
    unsigned char saved[3];
    for (int i=0;i<3;i++) { saved[i] = *(unsigned char*)targets[i]; *(unsigned char*)targets[i] = 0xCC; }

    uint32_t state[64];
    memset(state, 0x11, sizeof(state));
    uint8_t data[64]; memset(data, 'a', 64);
    HASH_DESC d[4];
    for (int i=0;i<4;i++){ d[i].ptr=data; d[i].blocks=1; d[i].pad=0; }

    // We can't easily know which int3 fired with one handler. Use different approach:
    // restore and patch one at a time, see if trap fires.
    for (int t=0;t<3;t++) {
        for (int i=0;i<3;i++) *(unsigned char*)targets[i] = saved[i];
        *(unsigned char*)targets[t] = 0xCC;
        which = t;
        fprintf(stderr, "trying %s\n", names[t]);
        sha256_multi_block(state, d, 1);
        fprintf(stderr, "returned normally for %s\n", names[t]);
    }
    return 0;
}
