/* Fully unrolled, message schedule computed on the fly, using scalar + bswap.
   Compiler auto-vectorization won't chain, but scheduling should be decent. */
#define ROR(x,n) __rorl(x,n)

static void transform(uint32_t s[8], const uint8_t block[64]) {
    uint32_t W[64];
    const uint32_t *in = (const uint32_t*)block;
    for (int i=0;i<16;i++) W[i] = __builtin_bswap32(in[i]);
    for (int i=16;i<64;i++) {
        uint32_t x = W[i-15];
        uint32_t y = W[i-2];
        uint32_t s0 = ROR(x,7) ^ ROR(x,18) ^ (x>>3);
        uint32_t s1 = ROR(y,17) ^ ROR(y,19) ^ (y>>10);
        W[i] = W[i-16] + s0 + W[i-7] + s1;
    }
    uint32_t a=s[0],b=s[1],c=s[2],d=s[3],e=s[4],f=s[5],g=s[6],h=s[7];
    #pragma unroll
    for (int i=0;i<64;i++) {
        uint32_t S1 = ROR(e,6)^ROR(e,11)^ROR(e,25);
        uint32_t ch = (e&f)^((~e)&g);
        uint32_t t1 = h + S1 + ch + K[i] + W[i];
        uint32_t S0 = ROR(a,2)^ROR(a,13)^ROR(a,22);
        uint32_t maj = (a&b)^(a&c)^(b&c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+S0+maj;
    }
    s[0]+=a; s[1]+=b; s[2]+=c; s[3]+=d; s[4]+=e; s[5]+=f; s[6]+=g; s[7]+=h;
}

static void sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t i=0;
    for (; i+64<=len; i+=64) transform(state, data+i);
    uint8_t block[64];
    size_t rem = len-i;
    memcpy(block, data+i, rem);
    block[rem++] = 0x80;
    if (rem > 56) { memset(block+rem,0,64-rem); transform(state, block); rem=0; }
    memset(block+rem, 0, 56-rem);
    uint64_t bits = (uint64_t)len*8;
    for (int j=0;j<8;j++) block[63-j]=(uint8_t)(bits>>(8*j));
    transform(state, block);
    for (int j=0;j<8;j++) {
        uint32_t v=__builtin_bswap32(state[j]);
        memcpy(out+4*j,&v,4);
    }
}

static double now(){ struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9; }

int main(){
    size_t n=20000*1024;
    uint8_t *data=malloc(n);
    memset(data, 0x5a, n);
    uint8_t o1[32], o2[32];
    sha256(data,n,o1);
    SHA256(data,n,o2);
    printf("match %d\n", memcmp(o1,o2,32)==0);
    double best=1e9,t0;
    for(int r=0;r<3;r++){ t0=now(); sha256(data,n,o1); double d=now()-t0; if(d<best)best=d; }
    printf("custom %.4f\n", best);
    best=1e9;
    for(int r=0;r<3;r++){ t0=now(); SHA256(data,n,o2); double d=now()-t0; if(d<best)best=d; }
    printf("openssl %.4f\n", best);
    return 0;
}
