static vDSP_Length next_good_len(vDSP_Length n) {
    if (n <= 2) return 2;
    /* pow2 */
    vDSP_Length p2 = 1;
    while (p2 < n) p2 <<= 1;
    vDSP_Length best = p2;
    const int fs[3] = {3, 5, 15};
    for (int i = 0; i < 3; i++) {
        int f = fs[i];
        vDSP_Length need = (n + f - 1) / f;
        vDSP_Length twok = 16;
        if (need > 16) {
            twok = 1;
            while (twok < need) twok <<= 1;
        }
        vDSP_Length cand = (vDSP_Length)f * twok;
        if (cand >= n && cand < best) best = cand;
    }
    return best;
}

Plan *plan_create(vDSP_Length n_out_hint) {
    vDSP_Length n = next_good_len(n_out_hint);
    Plan *p = calloc(1, sizeof(Plan));
    p->n = n;
