    p->yr = calloc(h, sizeof(double));
    p->yi = calloc(h, sizeof(double));
    p->zr = calloc(h, sizeof(double));
    p->zi = calloc(h, sizeof(double));
    p->or_ = calloc(h, sizeof(double));
    p->oi = calloc(h, sizeof(double));
