}

void plan_destroy(Plan *p) {
    if (!p) return;
    vDSP_DFT_DestroySetupD(p->fwd);
    vDSP_DFT_DestroySetupD(p->inv);
    free(p->xr); free(p->xi); free(p->yr); free(p->yi);
    free(p->zr); free(p->zi); free(p->or_); free(p->oi);
    free(p);
}

vDSP_Length plan_n(Plan *p) { return p->n; }

/* full convolution, writes n_out doubles to out. x,y contiguous double. */
void conv_full(Plan *p, const double *x, vDSP_Length nx, const double *y, vDSP_Length ny, double *out) {
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi, *Yr = p->yr, *Yi = p->yi;
    double *Zr = p->zr, *Zi = p->zi, *Or = p->or_, *Oi = p->oi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    vDSP_Length ne = (nx + 1) / 2;
    vDSP_Length no = nx / 2;
    for (vDSP_Length i = 0; i < ne; i++) Xr[i] = x[2*i];
    for (vDSP_Length i = 0; i < no; i++) Xi[i] = x[2*i+1];

    ne = (ny + 1) / 2;
    no = ny / 2;
    for (vDSP_Length i = 0; i < ne; i++) Yr[i] = y[2*i];
    for (vDSP_Length i = 0; i < no; i++) Yi[i] = y[2*i+1];

    vDSP_DFT_ExecuteD(p->fwd, Xr, Xi, Zr, Zi); /* use Zr/Zi as temp spectrum X, then copy? */
    /* Can't overwrite X input if in-place only allowed equal. We used Zr,Zi as output.
       Need to keep X spectrum. Let's swap: execute into Xr,Xi in place. */
}

/* redo properly */
void conv_full2(Plan *p, const double *x, vDSP_Length nx, const double *y, vDSP_Length ny, double *out, vDSP_Length n_out) {
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi;
    double *Yr = p->yr, *Yi = p->yi;
    double *Zr = p->zr, *Zi = p->zi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    for (vDSP_Length i = 0; i < nx; i++) {
        if ((i & 1) == 0) Xr[i >> 1] = x[i];
        else Xi[i >> 1] = x[i];
    }
    for (vDSP_Length i = 0; i < ny; i++) {
        if ((i & 1) == 0) Yr[i >> 1] = y[i];
        else Yi[i >> 1] = y[i];
    }

    /* in-place forward */
    vDSP_DFT_ExecuteD(p->fwd, Xr, Xi, Xr, Xi);
    vDSP_DFT_ExecuteD(p->fwd, Yr, Yi, Yr, Yi);

    /* complex multiply packed */
    Zr[0] = Xr[0] * Yr[0];
    Zi[0] = Xi[0] * Yi[0];
    for (vDSP_Length k = 1; k < h; k++) {
        double ar = Xr[k], ai = Xi[k], br = Yr[k], bi = Yi[k];
        Zr[k] = ar * br - ai * bi;
        Zi[k] = ar * bi + ai * br;
    }

    vDSP_DFT_ExecuteD(p->inv, Zr, Zi, Xr, Xi); /* even in Xr, odd in Xi */

    double scale = 1.0 / (4.0 * (double)n);
    vDSP_Length ne = (n_out + 1) / 2;
    vDSP_Length no = n_out / 2;
    for (vDSP_Length i = 0; i < ne; i++) out[2*i] = Xr[i] * scale;
    for (vDSP_Length i = 0; i < no; i++) out[2*i+1] = Xi[i] * scale;
}
