typedef struct {
    FFTSetupD setup;
    vDSP_Length log2n; /* N = 1<<log2n, N is full real length */
    vDSP_Length n;
    double *xr, *xi, *yr, *yi;
    double *br, *bi; /* temp buffer for zript */
} Plan;

static vDSP_Length next_pow2(vDSP_Length n) {
    vDSP_Length p = 1;
    vDSP_Length log = 0;
    while (p < n) { p <<= 1; log++; }
    return log; /* returns log2, p = 1<<log */
}

Plan *plan_create(vDSP_Length n_out_hint) {
    Plan *p = (Plan *)calloc(1, sizeof(Plan));
    vDSP_Length log = 0;
    vDSP_Length nn = 1;
    while (nn < n_out_hint) { nn <<= 1; log++; }
    if (log < 1) log = 1;
    p->log2n = log;
    p->n = (vDSP_Length)1 << log;
    p->setup = vDSP_create_fftsetupD(log, kFFTRadix2);
    vDSP_Length h = p->n / 2;
    p->xr = (double *)calloc(h, sizeof(double));
    p->xi = (double *)calloc(h, sizeof(double));
    p->yr = (double *)calloc(h, sizeof(double));
    p->yi = (double *)calloc(h, sizeof(double));
    p->br = (double *)calloc(h, sizeof(double));
    p->bi = (double *)calloc(h, sizeof(double));
    return p;
}

void plan_destroy(Plan *p) {
    if (!p) return;
    vDSP_destroy_fftsetupD(p->setup);
    free(p->xr); free(p->xi); free(p->yr); free(p->yi);
    free(p->br); free(p->bi);
    free(p);
}

vDSP_Length plan_n(Plan *p) { return p->n; }

void conv_full(Plan *p, const double *x, vDSP_Length nx,
               const double *y, vDSP_Length ny,
               double *out, vDSP_Length n_out) {
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi;
    double *Yr = p->yr, *Yi = p->yi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    for (vDSP_Length i = 0; i < nx; i++) {
        if ((i & 1u) == 0) Xr[i >> 1] = x[i];
        else Xi[i >> 1] = x[i];
    }
    for (vDSP_Length i = 0; i < ny; i++) {
        if ((i & 1u) == 0) Yr[i >> 1] = y[i];
        else Yi[i >> 1] = y[i];
    }

    DSPDoubleSplitComplex X = {Xr, Xi};
    DSPDoubleSplitComplex Y = {Yr, Yi};
    DSPDoubleSplitComplex buf = {p->br, p->bi};

    vDSP_fft_zriptD(p->setup, &X, 1, &buf, p->log2n, kFFTDirection_Forward);
    vDSP_fft_zriptD(p->setup, &Y, 1, &buf, p->log2n, kFFTDirection_Forward);

    /* packed complex multiply into X (overwrite) */
    /* DC and Nyquist are real, stored in realp[0] and imagp[0] */
    double dc = Xr[0] * Yr[0];
    double nyq = Xi[0] * Yi[0];
    /* k = 1..h-1 */
    /* use Y as scratch? do in place carefully into X using temp scalars */
    for (vDSP_Length k = 1; k < h; k++) {
