#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/*
 * Overlap-add FFT convolution using vDSP radix-2 real FFTs.
 * Block size chosen so each transform is a power of two, much smaller than
 * the full convolution length, and vectorized by Accelerate.
 */

typedef struct {
    FFTSetupD setup;
    vDSP_Length log2n;
    vDSP_Length n;       /* FFT length */
    vDSP_Length block;   /* input block size = n/2 */
    double *xr, *xi;     /* signal block spectrum / time */
    double *yr, *yi;     /* kernel spectrum (reused) */
    double *br, *bi;     /* temp */
    double *ola;         /* overlap accumulator, length block */
} Plan;

Plan *plan_create(vDSP_Length nfft_log_hint) {
    /* ignore hint; fixed good size. 2^16 = 65536 real FFT, block 32768 */
    Plan *p = (Plan *)calloc(1, sizeof(Plan));
    vDSP_Length log = 16; /* 65536 */
    p->log2n = log;
    p->n = (vDSP_Length)1 << log;
    p->block = p->n / 2;
    p->setup = vDSP_create_fftsetupD(log, kFFTRadix2);
    vDSP_Length h = p->n / 2;
    p->xr = (double *)calloc(h, sizeof(double));
    p->xi = (double *)calloc(h, sizeof(double));
    p->yr = (double *)calloc(h, sizeof(double));
    p->yi = (double *)calloc(h, sizeof(double));
    p->br = (double *)calloc(h, sizeof(double));
    p->bi = (double *)calloc(h, sizeof(double));
    p->ola = (double *)calloc(p->block, sizeof(double));
    return p;
}

void plan_destroy(Plan *p) {
    if (!p) return;
    vDSP_destroy_fftsetupD(p->setup);
    free(p->xr); free(p->xi); free(p->yr); free(p->yi);
    free(p->br); free(p->bi); free(p->ola);
    free(p);
}

static void pack_forward(Plan *p, const double *src, vDSP_Length ns, double *Rr, double *Ri) {
    vDSP_Length h = p->n / 2;
    memset(Rr, 0, h * sizeof(double));
    memset(Ri, 0, h * sizeof(double));
    for (vDSP_Length i = 0; i < ns; i++) {
        if ((i & 1u) == 0) Rr[i >> 1] = src[i];
        else Ri[i >> 1] = src[i];
    }
    DSPDoubleSplitComplex C = {Rr, Ri};
    DSPDoubleSplitComplex buf = {p->br, p->bi};
    vDSP_fft_zriptD(p->setup, &C, 1, &buf, p->log2n, kFFTDirection_Forward);
}

/* full linear convolution via overlap-add. out must have length nx+ny-1 */
void conv_full(Plan *p,
               const double *x, vDSP_Length nx,
               const double *y, vDSP_Length ny,
               double *out, vDSP_Length n_out) {
    /* Ensure kernel is the shorter one for fewer spectrum multiplies? 
       Actually kernel FFT is done once, so make the longer the kernel? 
       No: kernel FFT once regardless. Block the longer signal.
       If kernel longer than block, this simple plan can't handle it.
       For our sizes both ~1e5-2e5, block=32768, kernel may be longer.
       So we need kernel length <= block. If not, swap roles: block the other.
       If BOTH longer than block, we need a bigger FFT or to block both (2D OLA).
       Use a larger FFT if needed: recreate? For simplicity require n/2 >= min(nx,ny).
       We'll pick log so block >= min(nx, ny). Caller should create plan accordingly.
    */
    const double *sig = x; vDSP_Length ns = nx;
    const double *ker = y; vDSP_Length nk = ny;
    if (nk > p->block) {
        /* swap */
        sig = y; ns = ny;
        ker = x; nk = nx;
    }
    if (nk > p->block) {
        /* fallback shouldn't happen if plan sized right */
        fprintf(stderr, "kernel longer than block\n");
        return;
    }

    /* kernel spectrum */
    pack_forward(p, ker, nk, p->yr, p->yi);

    vDSP_Length h = p->n / 2;
    double scale = 0.25 / (double)p->n;
    vDSP_Length block = p->block;
    double *ola = p->ola;
    memset(ola, 0, block * sizeof(double));

    vDSP_Length produced = 0;
    vDSP_Length pos = 0;
    while (pos < ns) {
        vDSP_Length chunk = ns - pos;
        if (chunk > block) chunk = block;
        pack_forward(p, sig + pos, chunk, p->xr, p->xi);

        /* multiply spectra: X *= Y, packed */
        double dc = p->xr[0] * p->yr[0];
        double nyq = p->xi[0] * p->yi[0];
        for (vDSP_Length k = 1; k < h; k++) {
            double ar = p->xr[k], ai = p->xi[k], br = p->yr[k], bi = p->yi[k];
            p->xr[k] = ar * br - ai * bi;
            p->xi[k] = ar * bi + ai * br;
        }
        p->xr[0] = dc;
        p->xi[0] = nyq;

        DSPDoubleSplitComplex C = {p->xr, p->xi};
        DSPDoubleSplitComplex buf = {p->br, p->bi};
        vDSP_fft_zriptD(p->setup, &C, 1, &buf, p->log2n, kFFTDirection_Inverse);

        /* time result even in xr, odd in xi, length n, scale */
        /* overlap-add: first `block` samples are the new output contribution
           plus previous overlap; the remaining block samples are the new overlap
           (since kernel length <= block, overlap length = nk-1 <= block-1). */
        vDSP_Length out_remain = (produced < n_out) ? (n_out - produced) : 0;
        vDSP_Length emit = block;
        if (emit > out_remain) emit = out_remain;

        for (vDSP_Length i = 0; i < emit; i++) {
            double v = ((i & 1u) == 0 ? p->xr[i >> 1] : p->xi[i >> 1]) * scale;
            out[produced + i] = v + ola[i];
        }
        produced += emit;

        /* save new overlap (samples block .. n-1), only nk-1 matter, rest 0 */
        vDSP_Length ov = p->n - block; /* == block */
        for (vDSP_Length i = 0; i < ov; i++) {
            vDSP_Length idx = block + i;
            double v = ((idx & 1u) == 0 ? p->xr[idx >> 1] : p->xi[idx >> 1]) * scale;
            ola[i] = v;
        }
        pos += chunk;
    }
    /* any remaining overlap that extends into output (when last chunk doesn't fill)
       already handled because we emit `block` each time until n_out, and last
       iteration emits the tail including overlap via the emit loop? 
       Wait: last iteration only emits min(block, remain). The overlap of the
       last block is samples [chunk+nk-1 ...] which may exceed `block` if we only
       emit `block` and the true output continues into the overlap region.
       n_out = ns + nk - 1. After processing all signal, produced should reach
       ns (if we emit `block` each full step and a partial last). The remaining
       nk-1 samples live in ola. We need to flush ola.
    */
    if (produced < n_out) {
        vDSP_Length remain = n_out - produced;
        for (vDSP_Length i = 0; i < remain; i++) out[produced + i] = ola[i];
    }
}
