#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

/* ---------- list -> double array ---------- */
static int list_to_doubles(PyObject *list, double **out, Py_ssize_t *n_out) {
    Py_ssize_t n = PyList_GET_SIZE(list);
    double *a = (double *)malloc((n > 0 ? n : 1) * sizeof(double));
    if (!a) { PyErr_NoMemory(); return -1; }
    for (Py_ssize_t i = 0; i < n; i++) {
        PyObject *item = PyList_GET_ITEM(list, i);
        a[i] = PyFloat_AS_DOUBLE(item);
    }
    *out = a;
    *n_out = n;
    return 0;
}

/* ---------- vDSP radix-2 real convolution (full) ---------- */

typedef struct {
    FFTSetupD setup;
    vDSP_Length log2n;
    vDSP_Length n;
    double *xr, *xi, *yr, *yi, *br, *bi;
} Plan;

static Plan *plan_new(vDSP_Length n_out) {
    Plan *p = (Plan *)calloc(1, sizeof(Plan));
    vDSP_Length log = 0, nn = 1;
    if (n_out < 2) n_out = 2;
    while (nn < n_out) { nn <<= 1; log++; }
    p->log2n = log;
    p->n = nn;
    p->setup = vDSP_create_fftsetupD(log, kFFTRadix2);
    vDSP_Length h = nn / 2;
    p->xr = (double *)calloc(h, sizeof(double));
    p->xi = (double *)calloc(h, sizeof(double));
    p->yr = (double *)calloc(h, sizeof(double));
    p->yi = (double *)calloc(h, sizeof(double));
    p->br = (double *)calloc(h, sizeof(double));
    p->bi = (double *)calloc(h, sizeof(double));
    return p;
}

static void plan_free(Plan *p) {
    if (!p) return;
    vDSP_destroy_fftsetupD(p->setup);
    free(p->xr); free(p->xi); free(p->yr); free(p->yi);
    free(p->br); free(p->bi);
    free(p);
}

/* cache a few plans by log2n */
#define MAXLOG 24
static Plan *plan_cache[MAXLOG];

static Plan *plan_get(vDSP_Length n_out) {
    vDSP_Length log = 0, nn = 1;
    if (n_out < 2) n_out = 2;
    while (nn < n_out) { nn <<= 1; log++; }
    if (log >= MAXLOG) return plan_new(n_out); /* won't cache, leak-ok not expected */
    if (!plan_cache[log]) plan_cache[log] = plan_new(n_out);
    return plan_cache[log];
}

static void conv_full(const double *x, vDSP_Length nx,
                      const double *y, vDSP_Length ny,
                      double *out, vDSP_Length n_out) {
    Plan *p = plan_get(n_out);
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi, *Yr = p->yr, *Yi = p->yi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    for (vDSP_Length i = 0; i < nx; i++) {
        if ((i & 1u) == 0) Xr[i >> 1] = x[i];
        else Xi[i >> 1] = x[i];
    }
    for (vDSP_Length i = 0; i < ny; i++) {
        if ((i & 1u) == 0) Yr[i >> 1] = y[i];
        else Yi[i >> 1] = y[i];
    }

    DSPDoubleSplitComplex X = {Xr, Xi};
    DSPDoubleSplitComplex Y = {Yr, Yi};
    DSPDoubleSplitComplex buf = {p->br, p->bi};
    vDSP_fft_zriptD(p->setup, &X, 1, &buf, p->log2n, kFFTDirection_Forward);
    vDSP_fft_zriptD(p->setup, &Y, 1, &buf, p->log2n, kFFTDirection_Forward);

    double dc = Xr[0] * Yr[0];
    double nyq = Xi[0] * Yi[0];
    for (vDSP_Length k = 1; k < h; k++) {
        double ar = Xr[k], ai = Xi[k], br = Yr[k], bi = Yi[k];
        Xr[k] = ar * br - ai * bi;
        Xi[k] = ar * bi + ai * br;
    }
    Xr[0] = dc;
    Xi[0] = nyq;

    vDSP_fft_zriptD(p->setup, &X, 1, &buf, p->log2n, kFFTDirection_Inverse);

    double scale = 0.25 / (double)n;
    vDSP_Length ne = (n_out + 1) / 2;
    vDSP_Length no = n_out / 2;
    for (vDSP_Length i = 0; i < ne; i++) out[2 * i] = Xr[i] * scale;
    for (vDSP_Length i = 0; i < no; i++) out[2 * i + 1] = Xi[i] * scale;
}

static PyObject *py_convolve(PyObject *self, PyObject *args) {
