#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>

/* ---------- vDSP radix-2 real FFT convolution ---------- */

typedef struct {
    FFTSetupD setup;
    vDSP_Length log2n;
    vDSP_Length n;
    double *xr, *xi, *yr, *yi, *br, *bi;
} Plan;

#define MAXLOG 26
static Plan *plan_cache[MAXLOG];

static Plan *plan_new(vDSP_Length log) {
    Plan *p = (Plan *)calloc(1, sizeof(Plan));
    p->log2n = log;
    p->n = (vDSP_Length)1 << log;
    p->setup = vDSP_create_fftsetupD(log, kFFTRadix2);
    vDSP_Length h = p->n / 2;
    /* 32-byte alignment helps vDSP */
    posix_memalign((void **)&p->xr, 32, h * sizeof(double));
    posix_memalign((void **)&p->xi, 32, h * sizeof(double));
    posix_memalign((void **)&p->yr, 32, h * sizeof(double));
    posix_memalign((void **)&p->yi, 32, h * sizeof(double));
    posix_memalign((void **)&p->br, 32, h * sizeof(double));
    posix_memalign((void **)&p->bi, 32, h * sizeof(double));
    return p;
}

static Plan *plan_get(vDSP_Length n_out) {
    vDSP_Length log = 0, nn = 1;
    if (n_out < 2) n_out = 2;
    while (nn < n_out) { nn <<= 1; log++; }
    if (!plan_cache[log]) plan_cache[log] = plan_new(log);
    return plan_cache[log];
}

static void conv_full(const double *x, vDSP_Length nx,
                      const double *y, vDSP_Length ny,
                      double *out, vDSP_Length n_out) {
    Plan *p = plan_get(n_out);
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi, *Yr = p->yr, *Yi = p->yi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    for (vDSP_Length i = 0; i < nx; i += 2) {
        Xr[i >> 1] = x[i];
    }
    for (vDSP_Length i = 1; i < nx; i += 2) {
        Xi[i >> 1] = x[i];
    }
    for (vDSP_Length i = 0; i < ny; i += 2) {
        Yr[i >> 1] = y[i];
    }
    for (vDSP_Length i = 1; i < ny; i += 2) {
        Yi[i >> 1] = y[i];
    }

    DSPDoubleSplitComplex Xc = {Xr, Xi};
    DSPDoubleSplitComplex Yc = {Yr, Yi};
    DSPDoubleSplitComplex buf = {p->br, p->bi};
    vDSP_fft_zriptD(p->setup, &Xc, 1, &buf, p->log2n, kFFTDirection_Forward);
    vDSP_fft_zriptD(p->setup, &Yc, 1, &buf, p->log2n, kFFTDirection_Forward);

    double dc = Xr[0] * Yr[0];
    double nyq = Xi[0] * Yi[0];
    vDSP_Length k = 1;
    /* 2-way unroll */
    for (; k + 1 < h; k += 2) {
        double ar0 = Xr[k], ai0 = Xi[k], br0 = Yr[k], bi0 = Yi[k];
        double ar1 = Xr[k+1], ai1 = Xi[k+1], br1 = Yr[k+1], bi1 = Yi[k+1];
        Xr[k]   = ar0 * br0 - ai0 * bi0;
        Xi[k]   = ar0 * bi0 + ai0 * br0;
        Xr[k+1] = ar1 * br1 - ai1 * bi1;
        Xi[k+1] = ar1 * bi1 + ai1 * br1;
    }
    if (k < h) {
        double ar = Xr[k], ai = Xi[k], br = Yr[k], bi = Yi[k];
        Xr[k] = ar * br - ai * bi;
        Xi[k] = ar * bi + ai * br;
    }
    Xr[0] = dc;
    Xi[0] = nyq;

    vDSP_fft_zriptD(p->setup, &Xc, 1, &buf, p->log2n, kFFTDirection_Inverse);

    double scale = 0.25 / (double)n;
    /* interleave with scale, only n_out samples */
    vDSP_Length i = 0;
    vDSP_Length ne = n_out / 2;
    for (; i < ne; i++) {
        out[2 * i]     = Xr[i] * scale;
        out[2 * i + 1] = Xi[i] * scale;
    }
    if (n_out & 1u) {
        out[n_out - 1] = Xr[ne] * scale;
    }
}

/* slice full result according to scipy.signal.fftconvolve modes.
   same: length of first input, centered (start = (ny-1)//2)
   valid: length max(nx,ny)-min(nx,ny)+1, start = min(nx,ny)-1
*/
static void mode_slice(vDSP_Length nx, vDSP_Length ny, const char *mode,
                       vDSP_Length *start, vDSP_Length *length) {
    if (mode[0] == 's') { /* same */
        *length = nx; /* scipy: output length == first input */
        *start = (ny - 1) / 2;
    } else if (mode[0] == 'v') { /* valid */
        if (nx >= ny) {
            *length = nx - ny + 1;
            *start = ny - 1;
        } else {
            *length = ny - nx + 1;
            *start = nx - 1;
        }
    } else { /* full */
        *length = nx + ny - 1;
        *start = 0;
    }
}

static PyObject *py_convolve(PyObject *self, PyObject *args) {
    PyObject *lx, *ly;
    const char *mode = "full";
    if (!PyArg_ParseTuple(args, "OOs", &lx, &ly, &mode)) return NULL;

    Py_ssize_t nx = PyList_GET_SIZE(lx);
    Py_ssize_t ny = PyList_GET_SIZE(ly);
    if (nx == 0 || ny == 0) {
        npy_intp dims[1] = {0};
        return PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    }

    double *x = (double *)malloc(nx * sizeof(double));
    double *y = (double *)malloc(ny * sizeof(double));
    if (!x || !y) { free(x); free(y); return PyErr_NoMemory(); }

    for (Py_ssize_t i = 0; i < nx; i++) {
        x[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(lx, i));
    }
    for (Py_ssize_t i = 0; i < ny; i++) {
        y[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(ly, i));
    }

    vDSP_Length start, length;
    mode_slice((vDSP_Length)nx, (vDSP_Length)ny, mode, &start, &length);
    vDSP_Length n_full = (vDSP_Length)(nx + ny - 1);

    npy_intp dims[1] = {(npy_intp)length};
    PyObject *arr = PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    if (!arr) { free(x); free(y); return NULL; }
    double *out = (double *)PyArray_DATA((PyArrayObject *)arr);

    if (start == 0 && length == n_full) {
        conv_full(x, (vDSP_Length)nx, y, (vDSP_Length)ny, out, n_full);
    } else {
        /* compute full into temp then copy slice. For large valid this wastes
           work but keeps one code path. */
        double *full = (double *)malloc(n_full * sizeof(double));
        if (!full) { free(x); free(y); Py_DECREF(arr); return PyErr_NoMemory(); }
        conv_full(x, (vDSP_Length)nx, y, (vDSP_Length)ny, full, n_full);
        memcpy(out, full + start, length * sizeof(double));
        free(full);
    }
    free(x);
    free(y);
    return arr;
}

static PyMethodDef methods[] = {
    {"convolve", py_convolve, METH_VARARGS, "FFT convolve two lists"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastconv", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastconv(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
