#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <numpy/arrayobject.h>
#include <Accelerate/Accelerate.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

/* ---------------- plans ---------------- */

typedef struct {
    FFTSetupD setup;
    vDSP_Length log2n;
    vDSP_Length n;
    double *xr, *xi, *yr, *yi;
    double *br1, *bi1, *br2, *bi2;
} Plan;

#define MAXLOG 26
static Plan *plan_cache[MAXLOG];
static pthread_mutex_t plan_mu = PTHREAD_MUTEX_INITIALIZER;

static void *xalign(size_t bytes) {
    void *p = NULL;
    if (posix_memalign(&p, 64, bytes ? bytes : 64) != 0) return NULL;
    return p;
}

static Plan *plan_new(vDSP_Length log) {
    Plan *p = (Plan *)calloc(1, sizeof(Plan));
    p->log2n = log;
    p->n = (vDSP_Length)1 << log;
    p->setup = vDSP_create_fftsetupD(log, kFFTRadix2);
    vDSP_Length h = p->n / 2;
    size_t bytes = h * sizeof(double);
    p->xr = xalign(bytes); p->xi = xalign(bytes);
    p->yr = xalign(bytes); p->yi = xalign(bytes);
    p->br1 = xalign(bytes); p->bi1 = xalign(bytes);
    p->br2 = xalign(bytes); p->bi2 = xalign(bytes);
    return p;
}

static Plan *plan_get(vDSP_Length n_out) {
    vDSP_Length log = 0, nn = 1;
    if (n_out < 2) n_out = 2;
    while (nn < n_out) { nn <<= 1; log++; }
    pthread_mutex_lock(&plan_mu);
    if (!plan_cache[log]) plan_cache[log] = plan_new(log);
    Plan *p = plan_cache[log];
    pthread_mutex_unlock(&plan_mu);
    return p;
}

/* ---------------- parallel list->double ---------------- */

typedef struct {
    PyObject *list;
    double *dst;
    Py_ssize_t begin, end;
} ConvJob;

static void *convert_worker(void *arg) {
    ConvJob *j = (ConvJob *)arg;
    PyObject *list = j->list;
    double *dst = j->dst;
    for (Py_ssize_t i = j->begin; i < j->end; i++) {
        dst[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(list, i));
    }
    return NULL;
}

static void convert_list(PyObject *list, double *dst, Py_ssize_t n) {
    if (n < 8192) {
        for (Py_ssize_t i = 0; i < n; i++)
            dst[i] = PyFloat_AS_DOUBLE(PyList_GET_ITEM(list, i));
        return;
    }
    /* 4 threads. GIL must be held (we don't release it). */
    const int T = 4;
    pthread_t th[4];
    ConvJob jobs[4];
    Py_ssize_t chunk = (n + T - 1) / T;
    int started = 0;
    for (int t = 0; t < T; t++) {
        jobs[t].list = list;
        jobs[t].dst = dst;
        jobs[t].begin = t * chunk;
        jobs[t].end = jobs[t].begin + chunk;
        if (jobs[t].begin >= n) break;
        if (jobs[t].end > n) jobs[t].end = n;
        if (t == 0) {
            /* run chunk 0 on this thread after launching others */
        } else {
            pthread_create(&th[t], NULL, convert_worker, &jobs[t]);
            started++;
        }
    }
    convert_worker(&jobs[0]);
    for (int t = 1; t < T; t++) {
        if (jobs[t].begin < n) pthread_join(th[t], NULL);
    }
    (void)started;
}

/* ---------------- parallel forward FFTs ---------------- */

typedef struct {
    Plan *p;
    DSPDoubleSplitComplex *sig;
    DSPDoubleSplitComplex *buf;
} FFTJob;

static void *fft_worker(void *arg) {
    FFTJob *j = (FFTJob *)arg;
    vDSP_fft_zriptD(j->p->setup, j->sig, 1, j->buf, j->p->log2n, kFFTDirection_Forward);
    return NULL;
}

static void conv_full_into(Plan *p,
                           const double *x, vDSP_Length nx,
                           const double *y, vDSP_Length ny,
                           double *out, vDSP_Length out_off, vDSP_Length out_len,
                           double *scratch_full) {
    /* scratch_full length >= n (FFT length). If out covers the whole result
       and out_off==0 and out_len==n_full, we can write directly only if
       out_len region starts at 0. We always write the needed slice. */
    vDSP_Length n = p->n;
    vDSP_Length h = n / 2;
    double *Xr = p->xr, *Xi = p->xi, *Yr = p->yr, *Yi = p->yi;

    memset(Xr, 0, h * sizeof(double));
    memset(Xi, 0, h * sizeof(double));
    memset(Yr, 0, h * sizeof(double));
    memset(Yi, 0, h * sizeof(double));

    for (vDSP_Length i = 0; i < nx; i += 2) Xr[i >> 1] = x[i];
    for (vDSP_Length i = 1; i < nx; i += 2) Xi[i >> 1] = x[i];
    for (vDSP_Length i = 0; i < ny; i += 2) Yr[i >> 1] = y[i];
    for (vDSP_Length i = 1; i < ny; i += 2) Yi[i >> 1] = y[i];

    DSPDoubleSplitComplex Xc = {Xr, Xi};
    DSPDoubleSplitComplex Yc = {Yr, Yi};
    DSPDoubleSplitComplex b1 = {p->br1, p->bi1};
    DSPDoubleSplitComplex b2 = {p->br2, p->bi2};

    FFTJob jy = {p, &Yc, &b2};
    pthread_t th;
    pthread_create(&th, NULL, fft_worker, &jy);
    vDSP_fft_zriptD(p->setup, &Xc, 1, &b1, p->log2n, kFFTDirection_Forward);
    pthread_join(th, NULL);

    /* complex multiply, DC/Nyquist real */
    double dc = Xr[0] * Yr[0];
    double nyq = Xi[0] * Yi[0];
    vDSP_Length k = 1;
    for (; k + 3 < h; k += 4) {
        double ar0 = Xr[k], ai0 = Xi[k], br0 = Yr[k], bi0 = Yi[k];
        double ar1 = Xr[k+1], ai1 = Xi[k+1], br1v = Yr[k+1], bi1v = Yi[k+1];
        double ar2 = Xr[k+2], ai2 = Xi[k+2], br2v = Yr[k+2], bi2v = Yi[k+2];
        double ar3 = Xr[k+3], ai3 = Xi[k+3], br3v = Yr[k+3], bi3v = Yi[k+3];
        Xr[k]   = ar0*br0 - ai0*bi0; Xi[k]   = ar0*bi0 + ai0*br0;
        Xr[k+1] = ar1*br1v - ai1*bi1v; Xi[k+1] = ar1*bi1v + ai1*br1v;
        Xr[k+2] = ar2*br2v - ai2*bi2v; Xi[k+2] = ar2*bi2v + ai2*br2v;
        Xr[k+3] = ar3*br3v - ai3*bi3v; Xi[k+3] = ar3*bi3v + ai3*br3v;
    }
    for (; k < h; k++) {
        double ar = Xr[k], ai = Xi[k], br = Yr[k], bi = Yi[k];
        Xr[k] = ar*br - ai*bi;
        Xi[k] = ar*bi + ai*br;
    }
    Xr[0] = dc;
    Xi[0] = nyq;

    vDSP_fft_zriptD(p->setup, &Xc, 1, &b1, p->log2n, kFFTDirection_Inverse);

    double scale = 0.25 / (double)n;

    /* Extract out_len samples starting at out_off from interleaved even/odd. */
    vDSP_Length end = out_off + out_len;
    vDSP_Length i = out_off;
    /* align to even */
    if (i & 1u) {
        out[0] = Xi[i >> 1] * scale;
        i++;
        out++;
        out_len--;
    }
    vDSP_Length pairs = out_len / 2;
    vDSP_Length base = i >> 1;
    double *even = Xr + base;
    double *odd = Xi + base;
    for (vDSP_Length pidx = 0; pidx < pairs; pidx++) {
        out[2 * pidx]     = even[pidx] * scale;
        out[2 * pidx + 1] = odd[pidx] * scale;
    }
    if (out_len & 1u) {
        out[out_len - 1] = even[pairs] * scale;
    }
    (void)end;
}

static void mode_slice(vDSP_Length nx, vDSP_Length ny, const char *mode,
                       vDSP_Length *start, vDSP_Length *length) {
    if (mode[0] == 's') {
        *length = nx;
        *start = (ny - 1) / 2;
    } else if (mode[0] == 'v') {
        if (nx >= ny) {
            *length = nx - ny + 1;
            *start = ny - 1;
        } else {
            *length = ny - nx + 1;
            *start = nx - 1;
        }
    } else {
        *length = (nx + ny - 1);
        *start = 0;
    }
}

static PyObject *py_convolve(PyObject *self, PyObject *args) {
    PyObject *lx, *ly;
    const char *mode = "full";
    if (!PyArg_ParseTuple(args, "OOs", &lx, &ly, &mode)) return NULL;

    Py_ssize_t nx = PyList_GET_SIZE(lx);
    Py_ssize_t ny = PyList_GET_SIZE(ly);
    if (nx == 0 || ny == 0) {
        npy_intp dims[1] = {0};
        return PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    }

    double *x = (double *)malloc((size_t)nx * sizeof(double));
    double *y = (double *)malloc((size_t)ny * sizeof(double));
    if (!x || !y) { free(x); free(y); return PyErr_NoMemory(); }

    /* convert both lists in parallel (8-way across two lists via 4+4 would
       oversubscribe). Convert sequentially with internal 4 threads each —
       two sequential parallel conversions. */
    convert_list(lx, x, nx);
    convert_list(ly, y, ny);

    vDSP_Length start, length;
    mode_slice((vDSP_Length)nx, (vDSP_Length)ny, mode, &start, &length);
    vDSP_Length n_full = (vDSP_Length)(nx + ny - 1);

    npy_intp dims[1] = {(npy_intp)length};
    PyObject *arr = PyArray_SimpleNew(1, dims, NPY_FLOAT64);
    if (!arr) { free(x); free(y); return NULL; }
    double *out = (double *)PyArray_DATA((PyArrayObject *)arr);

    Plan *p = plan_get(n_full);
    conv_full_into(p, x, (vDSP_Length)nx, y, (vDSP_Length)ny,
                   out, start, length, NULL);
    free(x);
    free(y);
    return arr;
}

static PyMethodDef methods[] = {
    {"convolve", py_convolve, METH_VARARGS, "FFT convolve two lists"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastconv", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastconv(void) {
    import_array();
    return PyModule_Create(&moduledef);
}
